import{_ as t,o as a,c as i,a as o}from"./app.DLiRGumz.js";const g=JSON.parse('{"title":"📖 thegent: Complete User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/COMPLETE_USER_GUIDE.md","filePath":"guides/COMPLETE_USER_GUIDE.md","lastUpdated":1771558125000}'),n={name:"guides/COMPLETE_USER_GUIDE.md"};function s(l,e,r,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="📖-thegent-complete-user-guide" tabindex="-1">📖 thegent: Complete User Guide <a class="header-anchor" href="#📖-thegent-complete-user-guide" aria-label="Permalink to &quot;📖 thegent: Complete User Guide&quot;">​</a></h1><blockquote><p><strong>Status</strong>: Active | <strong>Last Updated</strong>: 2026-02-19 <strong>Purpose</strong>: Comprehensive documentation for all features, configurations, and advanced capabilities of thegent.</p></blockquote><hr><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h2><p><code>thegent</code> is an autonomous agent orchestration system designed for high-performance development workflows. It integrates multiple AI agents (Claude, Cursor, etc.) into a unified mesh with shared memory, conflict resolution, and shell optimizations.</p><hr><h2 id="_2-core-components" tabindex="-1">2. Core Components <a class="header-anchor" href="#_2-core-components" aria-label="Permalink to &quot;2. Core Components&quot;">​</a></h2><h3 id="_2-1-agent-mesh-formerly-heliosshield" tabindex="-1">2.1 Agent Mesh (formerly heliosShield) <a class="header-anchor" href="#_2-1-agent-mesh-formerly-heliosshield" aria-label="Permalink to &quot;2.1 Agent Mesh (formerly heliosShield)&quot;">​</a></h3><p>The Agent Mesh is the coordination layer that prevents agents from stepping on each other&#39;s toes.</p><ul><li><strong>Process Discovery</strong>: Automatically detects running agents.</li><li><strong>Shared Tasks</strong>: Global task list for multi-agent delegation.</li><li><strong>Conflict Resolution</strong>: AST-aware merging for parallel code changes.</li><li><strong>Locking</strong>: Atomic directory-level locks for safe resource access.</li></ul><h3 id="_2-2-shell-environment" tabindex="-1">2.2 Shell Environment <a class="header-anchor" href="#_2-2-shell-environment" aria-label="Permalink to &quot;2.2 Shell Environment&quot;">​</a></h3><p>A heavily optimized Zsh/Bash environment with:</p><ul><li><strong>Instant Prompt</strong>: Zero perceived startup lag (&lt; 5ms).</li><li><strong>Lazy Loading</strong>: Defer expensive tool initialization (nvm, pyenv) until first use.</li><li><strong>Eval Caching</strong>: Cache tool init strings to save hundreds of milliseconds.</li><li><strong>Safeguards</strong>: Fork explosion prevention and recursive command protection.</li></ul><h3 id="_2-3-hook-runtime-rust" tabindex="-1">2.3 Hook Runtime (Rust) <a class="header-anchor" href="#_2-3-hook-runtime-rust" aria-label="Permalink to &quot;2.3 Hook Runtime (Rust)&quot;">​</a></h3><p>The <code>thegent</code> hook system manages git hooks and task automation with minimal overhead.</p><ul><li><strong>Native Performance</strong>: Built in Rust for &lt;50ms dispatch time.</li><li><strong>Parallel Execution</strong>: Run multiple hooks simultaneously with serialized output.</li></ul><hr><h2 id="_3-installation-setup" tabindex="-1">3. Installation &amp; Setup <a class="header-anchor" href="#_3-installation-setup" aria-label="Permalink to &quot;3. Installation &amp; Setup&quot;">​</a></h2><h3 id="_3-1-basic-installation" tabindex="-1">3.1 Basic Installation <a class="header-anchor" href="#_3-1-basic-installation" aria-label="Permalink to &quot;3.1 Basic Installation&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kooshapari/thegent/main/scripts/bootstrap.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_3-2-full-setup" tabindex="-1">3.2 Full Setup <a class="header-anchor" href="#_3-2-full-setup" aria-label="Permalink to &quot;3.2 Full Setup&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --full</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This configures:</p><ol><li><strong>Shell</strong>: Integration with <code>.zshrc</code> / <code>.bashrc</code>.</li><li><strong>Providers</strong>: Login to Anthropic, OpenAI, Gemini.</li><li><strong>Hooks</strong>: Git hook installation.</li><li><strong>Skills</strong>: Syncing system prompts to agents.</li></ol><hr><h2 id="_4-using-the-cli" tabindex="-1">4. Using the CLI <a class="header-anchor" href="#_4-using-the-cli" aria-label="Permalink to &quot;4. Using the CLI&quot;">​</a></h2><h3 id="_4-1-mesh-commands" tabindex="-1">4.1 Mesh Commands <a class="header-anchor" href="#_4-1-mesh-commands" aria-label="Permalink to &quot;4.1 Mesh Commands&quot;">​</a></h3><p>Manage the agent coordination layer:</p><ul><li><code>thegent mesh status</code>: View active agents and their heartbeats.</li><li><code>thegent mesh discover</code>: Scan for and register new agent processes.</li><li><code>thegent mesh tasks</code>: View and manage the global task queue.</li></ul><h3 id="_4-2-shell-commands" tabindex="-1">4.2 Shell Commands <a class="header-anchor" href="#_4-2-shell-commands" aria-label="Permalink to &quot;4.2 Shell Commands&quot;">​</a></h3><p>Optimize and debug your environment:</p><ul><li><code>thegent shell benchmark</code>: Measure shell startup performance.</li><li><code>thegent shell doctor</code>: Diagnose and fix environment issues.</li><li><code>thegent shell clear-cache</code>: Clear the eval and tool caches.</li></ul><h3 id="_4-3-general-commands" tabindex="-1">4.3 General Commands <a class="header-anchor" href="#_4-3-general-commands" aria-label="Permalink to &quot;4.3 General Commands&quot;">​</a></h3><ul><li><code>thegent run &quot;&lt;task&gt;&quot;</code>: Execute an autonomous task.</li><li><code>thegent serve</code>: Start the MCP server for external tool integration.</li></ul><hr><h2 id="_5-advanced-configuration" tabindex="-1">5. Advanced Configuration <a class="header-anchor" href="#_5-advanced-configuration" aria-label="Permalink to &quot;5. Advanced Configuration&quot;">​</a></h2><h3 id="_5-1-thegentsettings-config-thegent-config-yaml" tabindex="-1">5.1 ThegentSettings (<code>~/.config/thegent/config.yaml</code>) <a class="header-anchor" href="#_5-1-thegentsettings-config-thegent-config-yaml" aria-label="Permalink to &quot;5.1 ThegentSettings (`~/.config/thegent/config.yaml`)&quot;">​</a></h3><p>You can customize the behavior of <code>thegent</code> via its configuration file:</p><ul><li><code>harness_root</code>: Path to the mesh coordination directory (default: <code>~/.agent-harness</code>).</li><li><code>log_level</code>: Detail level for system logs.</li><li><code>shell_optimization_enabled</code>: Toggle for advanced shell features.</li></ul><h3 id="_5-2-environment-variables" tabindex="-1">5.2 Environment Variables <a class="header-anchor" href="#_5-2-environment-variables" aria-label="Permalink to &quot;5.2 Environment Variables&quot;">​</a></h3><ul><li><code>THGENT_AGENT_SHELL</code>: Preferred shell for agent-spawned processes.</li><li><code>THGENT_INSTANT_PROMPT</code>: Set to <code>0</code> to disable the instant prompt feature.</li></ul><hr><h2 id="_6-security-governance" tabindex="-1">6. Security &amp; Governance <a class="header-anchor" href="#_6-security-governance" aria-label="Permalink to &quot;6. Security &amp; Governance&quot;">​</a></h2><p><code>thegent</code> implements several layers of security:</p><ul><li><strong>Sensitive File Relocation</strong>: Credentials are moved to <code>~/.config/thegent/</code> with strict permissions.</li><li><strong>Action Artifacts</strong>: Every significant agent action is logged and signed (MAIF).</li><li><strong>Resource Isolation</strong>: Limits on CPU, memory, and file descriptors via <code>ulimit</code>.</li></ul><hr><h2 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to &quot;7. Troubleshooting&quot;">​</a></h2><h3 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h3><ul><li><strong>ELOOP (Too many symbolic links)</strong>: Usually caused by recursive directory structures in the mesh root. Fix with <code>thegent mesh reset</code>.</li><li><strong>&quot;command not found&quot; (after install)</strong>: Ensure <code>~/.local/bin</code> is in your <code>PATH</code> or run <code>thegent shell doctor --fix</code>.</li><li><strong>Agent collisions</strong>: Ensure all agents are registered via <code>thegent mesh discover</code>.</li></ul><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./QUICK_START.html">QUICK_START.md</a> - Get started in 5 minutes.</li><li><a href="./../architecture/ARCHITECTURE_LAYERS.html">ARCHITECTURE_LAYERS.md</a> - Internal design overview.</li><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> - Project development status.</li></ul>',52)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
